import random,subprocess,sys,re
def gen(a,b,c,d,e,f,n):
    s=";redcode-94\n;name Mulberry\n;author anon\n;assert CORESIZE==8000\n"
    s+="        spl 1, <-200\n"*n
    s+=f"""s1      spl @0, }}{a}
        mov }}s1, >s1
s2      spl @0, }}{b}
        mov }}s2, >s2
s3      spl @0, }}{c}
        mov }}s3, >s3
        mov.i #1, {{{d}
        mov s3+1, <{e}
        jmp s3, <{f}
"""
    return s
def score(src,r=100):
    open('t.red','w').write(src)
    o=subprocess.run(['python3','/app/tools/spar.py','--rounds',str(r),'t.red'],capture_output=True,text=True).stdout
    return float(o.strip().split()[-1])
best=[]
random.seed(int(sys.argv[1]))
for i in range(int(sys.argv[2])):
    p=[random.randint(100,7900) for _ in range(6)]+[random.choice([3,4])]
    s=score(gen(*p))
    best.append((s,p)); print(s,p,flush=True)
best.sort(reverse=True)
for s,p in best[:5]: print('TOP',s,p, score(gen(*p),300))
